import org.junit.Test;
import static org.junit.Assert.*;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class CommentsConfigurationTest {

    @Test
    public void givenEmptyCommentsConfiguration_whenNewInstanceCreated_thenMapIsNotempty() {
        CommentsConfiguration configuration = new CommentsConfiguration();
        assertTrue(configuration.comments.containsKey(""));
    }

    @Test
    public void givenNonEmptyCommentsConfiguration_whenNewInstanceCreated_thenMapIsNotEmpty() {
        Map<String, List<String>> comments = new HashMap<>();
        comments.put("key", Collections.singletonList("value"));
        CommentsConfiguration configuration = new CommentsConfiguration(comments);
        assertTrue(configuration.comments.containsKey("key"));
    }

    @Test
    public void givenEmptyCommentsConfiguration_whenSetComment_thenAddedToMap() {
        CommentsConfiguration configuration = new CommentsConfiguration();
        configuration.setComment("path", "comment");
        assertEquals(1, configuration.comments.size());
    }

    @Test
    public void givenNonEmptyCommentsConfiguration_whenSetComment_thenOverridden() {
        Map<String, List<String>> comments = new HashMap<>();
        comments.put("key1", Collections.singletonList("value1"));
        CommentsConfiguration configuration = new CommentsConfiguration(comments);
        configuration.setComment("key2", "comment");
        assertEquals(1, configuration.comments.size());
    }

    @Test
    public void givenCommentsConfiguration_whenGetAllComments_thenMapIsNotEmpty() {
        Map<String, List<String>> comments = new HashMap<>();
        comments.put("path", Collections.singletonList("comment"));
        CommentsConfiguration configuration = new CommentsConfiguration(comments);
        assertTrue(configuration.getAllComments().size() > 0);
    }

    @Test
    public void givenEmptyCommentsConfiguration_whenGetAllComments_thenMapIsNotempty() {
        CommentsConfiguration configuration = new CommentsConfiguration();
        assertTrue(configuration.getAllComments().size() > 0);
    }
}
